idx = ["# Reading notes index", "", "Nine notes from open-access PDFs in `bibliometrics\\pdfs\\`. Page numbers are PDF page numbers (page 1 = first page of the PDF). Quotations were machine-checked against the PDF text.", "", "| Note | Source | Takeaway |", "|---|---|---|"]
for n in N:
    pg = pages(n["file"]); q = []
    for qq in n["quotes"]:
        hit = [i + 1 for i, p in enumerate(pg) if norm(qq) in p]
        assert hit, (n["file"], qq)
        q.append(f'- "{qq}" (PDF p.{hit[0]})')
    body = (f"# {n['fn'][:-3]}\n\n**Citation:** {n['cite']}\n\n**What was read:** {n['depth']} Notes come from the text itself; nothing was filled from memory.\n\n"
            f"- **Research question:** {n['rq']}\n- **Data and sample:** {n['data']}\n- **Method and identification:** {n['method']}\n- **Main results:** {n['results']}\n- **Limitations stated by the authors:** {n['lim']}\n\n"
            "**Verbatim quotations (under 40 words each):**\n" + "\n".join(q) + f"\n\n**Bearing on Sean's paper:** {n['rel']}\n")
    open(os.path.join(ROOT, "depth", "reading-notes", n["fn"]), "w", encoding="utf8").write(body)
    idx.append(f"| {n['fn']} | {n['short']} | {n['take']} |")
open(os.path.join(ROOT, "depth", "reading-notes", "00-index.md"), "w", encoding="utf8").write("\n".join(idx) + "\n")
print("ok", len(N))
